// The seam of the fourth fix with the OLD logic: the files run one after the other and the run STOPS at the first file that is cut.
const testArgs = (files) => ['--test', '--test-reporter=tap', '--test-concurrency=1', '--test-timeout=900000', ...files];

async function decide(files, runFile) {
  for (const file of files) {
    const result = await runFile(file);
    if (result.code !== 0) {
      const named = result.failing.filter((name) => !/\.test\.cjs$/.test(name));
      if (result.code === null || named.length === 0) return { killed: null, undecided: true, killedBy: `${path.basename(file)} (cut, no named failing test)`, failingTests: result.failing.slice(0, 3), exit: result.code };
      return { killed: true, killedBy: path.basename(file), failingTests: named.slice(0, 3), exit: result.code };
    }
  }
  return { killed: false, killedBy: null, failingTests: [], exit: 0 };
}

